// Generates TypeScript types from the data contract's JSON Schemas
// (../src/atlas_da_lavoura/serving/schemas/) into src/types/data/. The output is not
// committed: it is regenerated by `npm run setup` and by CI, so the types can never
// drift from the schemas.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { compileFromFile } from "json-schema-to-typescript";

const webRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const schemasDir = path.join(webRoot, "..", "src", "atlas_da_lavoura", "serving", "schemas");
const outDir = path.join(webRoot, "src", "types", "data");

const banner =
  "/* Generated from src/atlas_da_lavoura/serving/schemas by scripts/generate-types.mjs." +
  " Do not edit: run `npm run generate-types`. */";

async function main() {
  fs.rmSync(outDir, { recursive: true, force: true });
  fs.mkdirSync(outDir, { recursive: true });
  const schemas = fs
    .readdirSync(schemasDir)
    .filter((name) => name.endsWith(".schema.json") && name !== "common.schema.json")
    .sort();
  for (const name of schemas) {
    const types = await compileFromFile(path.join(schemasDir, name), {
      cwd: schemasDir,
      bannerComment: banner,
      additionalProperties: false,
    });
    const out = path.join(outDir, name.replace(".schema.json", ".ts"));
    fs.writeFileSync(out, types);
    console.log(`wrote ${path.relative(webRoot, out)}`);
  }
}

main().catch((error) => {
  console.error(String(error));
  process.exit(1);
});
